import{_ as i,o as t,c as o,a0 as n}from"./chunks/framework.CShDTZbC.js";const h=JSON.parse('{"title":"Micro1 Hackathon - Engineering Scorecard","description":"","frontmatter":{},"headers":[],"relativePath":"competition-scorecard.md","filePath":"competition-scorecard.md"}'),a={name:"competition-scorecard.md"};function r(s,e,l,c,d,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="micro1-hackathon-engineering-scorecard" tabindex="-1">Micro1 Hackathon - Engineering Scorecard <a class="header-anchor" href="#micro1-hackathon-engineering-scorecard" aria-label="Permalink to &quot;Micro1 Hackathon - Engineering Scorecard&quot;">​</a></h1><p>This scorecard translates the official 100-point rubric into actionable engineering and project management tasks.</p><h2 id="_1-problem-user-value-15-points" tabindex="-1">1. Problem &amp; User Value (15 Points) <a class="header-anchor" href="#_1-problem-user-value-15-points" aria-label="Permalink to &quot;1. Problem &amp; User Value (15 Points)&quot;">​</a></h2><p><strong>What the judge is looking for:</strong> A clearly defined user with a meaningful bottleneck that actually matters. <strong>Evidence needed:</strong></p><ul><li>A clear description of the user.</li><li>Explanation of the bottleneck.</li><li>Why solving it is valuable in practice. <strong>Engineering Decisions to Improve Score:</strong></li><li>Focus on a specific, narrow problem rather than a generic &quot;assistant&quot;.</li><li>Ensure the problem is grounded in a real-world workflow. <strong>Mistakes that reduce score:</strong></li><li>Vague user persona.</li><li>Solving a non-existent or trivial bottleneck.</li></ul><h2 id="_2-agent-solution-engineering-30-points" tabindex="-1">2. Agent Solution &amp; Engineering (30 Points) <a class="header-anchor" href="#_2-agent-solution-engineering-30-points" aria-label="Permalink to &quot;2. Agent Solution &amp; Engineering (30 Points)&quot;">​</a></h2><p><strong>What the judge is looking for:</strong> Purposeful use of agents and technically sound implementation. <strong>Evidence needed:</strong></p><ul><li>Code that uses context, tools, memory, verification, skills, or orchestration <em>only when necessary</em>.</li><li>Explanations of <em>why</em> each design choice was made and how it solved the problem. <strong>Engineering Decisions to Improve Score:</strong></li><li>Justify every agent component.</li><li>Keep the architecture as simple as possible to achieve the goal reliably. <strong>Mistakes that reduce score:</strong></li><li>Over-engineering (e.g., adding 5 agents when 1 would do).</li><li>Adding components without a clear, measurable benefit.</li></ul><h2 id="_3-end-to-end-quality-20-points" tabindex="-1">3. End to End Quality (20 Points) <a class="header-anchor" href="#_3-end-to-end-quality-20-points" aria-label="Permalink to &quot;3. End to End Quality (20 Points)&quot;">​</a></h2><p><strong>What the judge is looking for:</strong> A realistic, self-contained execution that produces a polished, usable final result. <strong>Evidence needed:</strong></p><ul><li>The final output generated by the agent.</li><li>A workflow that completes from start to finish without awkward manual interventions (unless explicitly designed as a human checkpoint). <strong>Engineering Decisions to Improve Score:</strong></li><li>Format the output nicely (e.g., structured reports, clean code, proper summaries).</li><li>Ensure the result does not look like a generic &quot;ChatGPT&quot; draft. <strong>Mistakes that reduce score:</strong></li><li>Output that requires heavy manual editing to be usable.</li><li>&quot;Obvious AI-generated draft&quot; tone.</li></ul><h2 id="_4-measured-improvement-15-points" tabindex="-1">4. Measured Improvement (15 Points) <a class="header-anchor" href="#_4-measured-improvement-15-points" aria-label="Permalink to &quot;4. Measured Improvement (15 Points)&quot;">​</a></h2><p><strong>What the judge is looking for:</strong> Proof that your solution is better than a reasonable baseline. <strong>Evidence needed:</strong></p><ul><li>A simple baseline implementation.</li><li>The same evaluation cases run on both baseline and agent.</li><li>A changelog connecting iterations to evidence. <strong>Engineering Decisions to Improve Score:</strong></li><li>Build a solid, fair baseline (don&#39;t &quot;sandbag&quot; it).</li><li>Automate the evaluation of the 10+ cases to prove consistency.</li><li>Document every iteration, including failures, in the changelog. <strong>Mistakes that reduce score:</strong></li><li>Unfair baseline comparison.</li><li>Missing changelog entries.</li><li>Claims of improvement without evidence.</li></ul><h2 id="_5-reproducibility-15-points" tabindex="-1">5. Reproducibility (15 Points) <a class="header-anchor" href="#_5-reproducibility-15-points" aria-label="Permalink to &quot;5. Reproducibility (15 Points)&quot;">​</a></h2><p><strong>What the judge is looking for:</strong> The ability to run your project and get the same results from a clean environment. <strong>Evidence needed:</strong></p><ul><li>A comprehensive Reproduction Guide (setup, commands, data, expected output, versions, runtime, cost).</li><li>Access to the required data (public/synthetic/anonymous). <strong>Engineering Decisions to Improve Score:</strong></li><li>Provide a <code>requirements.txt</code> or <code>package.json</code>.</li><li>Script the setup process if possible.</li><li>Avoid hardcoded local paths or relying on private credentials. <strong>Mistakes that reduce score:</strong></li><li>Missing setup instructions.</li><li>Code that only runs on the creator&#39;s machine.</li><li>Requiring private data the judges cannot access.</li></ul><h2 id="_6-hot-take-insights-5-points" tabindex="-1">6. Hot Take / Insights (5 Points) <a class="header-anchor" href="#_6-hot-take-insights-5-points" aria-label="Permalink to &quot;6. Hot Take / Insights (5 Points)&quot;">​</a></h2><p><strong>What the judge is looking for:</strong> A practical lesson learned from a failure mode. <strong>Evidence needed:</strong></p><ul><li>An entry in the deliverables documenting a failure mode and the resulting insight. <strong>Engineering Decisions to Improve Score:</strong></li><li>Actively look for edge cases where the agent fails.</li><li>Document a removed experiment that failed and explain <em>why</em> it failed in the context of building reliable agents. <strong>Mistakes that reduce score:</strong></li><li>Ignoring failures.</li><li>Providing a generic observation instead of a practical lesson.</li></ul>',20)])])}const p=i(a,[["render",r]]);export{h as __pageData,p as default};
